INSERT INTO vi_source_base (company_id, title, source_type, publisher, publish_date, url, reliability, verify_status, retrieved_on, summary, limitations) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国建筑 2025 年年度报告', '定期报告', '中国建筑', '2026-04-18', 'https://www.cscec.com/tzzgxnew/dqbg_new/202604/P020260417798519591498.pdf', '一级·法定披露', '已读原文', '2026-07-27', '新签合同总额 45,458 亿元（建筑 41,510、地产合约销售 3,948）；营业收入 20,821 亿元（−4.8%）；归母净利 390.7 亿元（−15.4%）；经营现金流 205.4 亿元；分业务收入与毛利率；减值 258.7 亿元；2026 年目标新签 4.6 万亿元、营收 2.1 万亿元。', '本地 PDF 与 MinerU 解析全文：~/Desktop/二级市场/价值投资/中国建筑/原始资料/S01。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国建筑 2023 年年度报告', '定期报告', '中国建筑', '2024-04-30', 'https://www.cscec.com/tzzgxnew/dqbg_new/202404/P020240430429513167584.pdf', '一级·法定披露', '已读原文', '2026-07-27', '新签合同总额 2023 年 43,241 亿元、2022 年 39,031 亿元；归母净利 542.6 亿元；加权 ROE 13.36%。', '本地 PDF 与 MinerU 解析全文：~/Desktop/二级市场/价值投资/中国建筑/原始资料/S00。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国建筑 2026 年第一季度报告', '定期报告', '中国建筑', '2026-04-29', 'https://www.cscec.com/tzzgxnew/dqbg_new/202604/P020260428708440807985.pdf', '一级·法定披露', '已读原文', '2026-07-27', '一季度营收 5,118 亿元（−7.8%）、归母净利 138.8 亿元（−7.5%）、经营现金流 −770 亿元。', '本地 PDF 与 MinerU 解析全文：~/Desktop/二级市场/价值投资/中国建筑/原始资料/S02。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国建筑 2026 年半年度报告', '定期报告', '中国建筑', '2026-08-28', NULL, '一级·法定披露', '已读原文', '2026-10-22', '营收 9,758 亿元（−12.0%）、归母净利 230.0 亿元（−24.3%）、扣非 199.2 亿元；经营现金流 −284.6 亿元（同比少流出 544 亿元）；分部利润总额：房建 159.4、基建 101.1、地产 137.4 亿元；中国海外发展上半年净利 74.3 亿元；资产负债率 77.1%。', '经岗底斯取得公告原文（全文 file-id 87289711、摘要 87289417）；本地未下载 PDF。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '2026 年经营情况简报（1—6、1—7、1—8、1—9 月）', '临时公告', '中国建筑', '2026-10-20', NULL, '一级·法定披露', '已读原文', '2026-10-22', '1—9 月新签合同总额 32,890 亿元（−0.1%）：建筑 30,503 亿元（+0.4%；房建 +3.5%、基建 −5.8%；境外 2,599 亿元 +71.6%）；地产合约销售 2,386 亿元（−6.5%）、面积 660 万㎡（−30.6%）；房建新开工面积 15,928 万㎡（−18.1%）、竣工面积 −11.6%；期末土储 6,336 万㎡。', '经岗底斯取得公告原文（1—9 月 file-id 97337679）。简报是阶段性数据，可能与定期报告有差异。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '关于控股股东增持公司股份计划及进展的公告（2026-07-20、09-02、10-16）', '临时公告', '中国建筑', '2026-10-16', NULL, '一级·法定披露', '已读原文', '2026-10-22', '中建集团计划 12 个月内增持 5—10 亿元（集中竞价），已获增持资金贷款支持；截至 2026-09-02 持股 57.73%；上市以来第 8 次增持，无减持。', NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '关于 2026 年半年度计提资产减值准备的公告', '临时公告', '中国建筑', '2026-08-28', NULL, '一级·法定披露', '仅定位入口', '2026-10-22', '上半年计提资产及信用减值 100.4 亿元：应收账款 53.6、合同资产 24.8、存货 6.6、其他 15.4 亿元。', '分项数字来自业绩说明会问答，公告原文未下载。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '2025 年度业绩说明会问答（2026-04-20）', '数据库取数', '岗底斯（投资者问答）', '2026-04-20', NULL, '三级·第三方数据', '待核验', '2026-10-22', '政府债权回收超 1,500 亿元、逾期减少约 1,500 亿元；盘活存量资产 1,596 亿元；PPP：2023-11 后未新增，在施 416 个、权益投资 5,951 亿元；2025 年减值 258.7 亿元（信用 186.6、资产 72.1）；施工毛利率 8.8%（+0.7pt）、地产 14.4%（−2.9pt）；经营现金流 2023—2025 年 110、158、205 亿元。', '由岗底斯整理的问答记录，是管理层口径；关键数字需以定期报告核对。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '2026 年半年度业绩说明会问答（2026-08-31）', '数据库取数', '岗底斯（投资者问答、会议纪要）', '2026-08-31', NULL, '三级·第三方数据', '待核验', '2026-10-22', '上半年收款超 9,400 亿元、清收政府逾期债权超 800 亿元、盘活存量资产 1,132 亿元；减值分项；预计全年减值不超过去年、全年经营现金流在上年基础上增长；新接项目毛利率 +0.2pt；综合融资成本 −14bp、利息费用 −9.8%；建筑市场占有率 +2.2pt；地产未来两三年营收平稳或小幅波动。', '由岗底斯整理的问答记录，是管理层口径；关键数字需以定期报告核对。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '券商策略会交流纪要：公司董办（中泰证券，2026-07-14）', '数据库取数', '岗底斯（券商会议纪要）', '2026-07-14', NULL, '三级·第三方数据', '待核验', '2026-10-22', '“仍在艰难摸底”、全年利润承压、前低后高；2025 年减值构成（正常账龄 80—100 亿、专项约 150 亿，其中风险房企近半、地产存货约 1/5、PPP/BT）；政府背景业主占房建基建项目 40% 以上；海外订单占比不足 5%，五年目标 7%—8%；住宅占房建订单 20% 以内。', '由岗底斯整理的问答记录，是管理层口径；关键数字需以定期报告核对。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '上证 e 互动问答（2026-04 至 2026-10）', '官方网站', '上海证券交易所', '2026-10-20', 'https://sns.sseinfo.com/', '一级·法定披露', '已读原文', '2026-10-22', '2026 年度每股派息保持平稳；上市以来累计分红 1,040 亿元；控股股东无减持；今年重点推进租赁住房、商业不动产 REITs。', NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '东方财富 F10：中国建筑 2013—2025 年及 2026 年中报三大报表', '数据库取数', '东方财富', '2026-10-22', 'https://emweb.securities.eastmoney.com/PC_HSF10/NewFinanceAnalysis/Index?type=web&code=SH601668', '三级·第三方数据', '数值已核对', '2026-10-22', '利润表、现金流量表、资产负债表全部科目；2023—2025 年与年报一致。原始响应保存在 companies/601668_中国建筑/data/。', '带息负债为本框架口径（短期借款＋一年内到期非流动负债＋长期借款＋应付债券＋租赁负债），一年内到期非流动负债含少量非借款项目；Wind 积分不足，未用 Wind 交叉核对。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '历年年报与半年报经营数据片段（2017—2021 年新签合同额）', '定期报告', '中国建筑', '2022-04-16', NULL, '一级·法定披露', '数值已核对', '2026-10-22', '新签合同总额 2017 年 24,535、2018 年 26,271 亿元；建筑新签 2019 年 24,863、2020 年 27,721 亿元；地产合约销售 2020 年 4,287 亿元（+12.1%）；2020 年合计 3.2 万亿元（+11.6%）；2021 年 3.53 万亿元（+10.3%）。', '经岗底斯知识库检索取得 2018、2020、2021 年年报与股东大会资料原文片段，全文未下载。2019 年总额按 2020 年地产销售与增速反推；2021 年只有取整数。2014—2016 年未取得。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '东方财富数据中心：历年分红实施方案', '数据库取数', '东方财富', '2026-10-22', NULL, '三级·第三方数据', '数值已核对', '2026-10-22', '2013—2025 年度每股现金分红与登记日总股本；2017 年度 10 转 4 派 2.15 元（转增前股本 299.89 亿股）。', '分红总额＝每股股息×登记日总股本，与年报披露可能差几百万元。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '岗底斯：卖方一致预期与 2026 年中报点评（11 家）', '数据库取数', '岗底斯', '2026-10-21', NULL, '三级·第三方数据', '待核验', '2026-10-22', '一致预期（2026-10-21）2026—2028 年归母净利 369.6/381.6/391.6 亿元；中报后各家 2026 年预测 327.8—365.7 亿元（国投、广发、东方财富、华泰、中泰、财通、国盛等）；目标价 4.8 元（国投 6 倍 PE）、5.63 元（广发 7 倍 PE）、6.87 元（华泰分部估值）。', '卖方预测普遍偏乐观且中报后集体下调，只作对照，不直接进入模型。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '腾讯行情 K 线：中国建筑日线（2025-10—2026-10）', '数据库取数', '腾讯财经', '2026-10-22', 'https://web.ifzq.gtimg.cn/appstock/app/fqkline/get?param=sh601668,day', '三级·第三方数据', '数值已核对', '2026-10-22', '245 个交易日不复权收盘价；2026-10-22 收盘 4.50 元。', NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '本地持续投研（2026-07-27 起）：中国建筑价值投资深度报告与财务模型', '研究推导', '本研究', '2026-08-04', NULL, '研究推导', '已读原文', '2026-10-22', '当时结论：观察（周期/资产价值，安全边际不足）；PE 45%＋PB 40%＋DDM 15% 加权，三情景 3.78/5.27/6.80 元（价格 4.76 元，2026-08-03）。', '旧项目文件夹已于 2026-10-23 删除，以本工作台为准；原始 PDF 与解析全文并入 ~/Desktop/二级市场/价值投资/中国建筑/原始资料/，旧报告与模型可在 ~/Desktop/二级市场 的 git 提交 90ef92919 中找回。口径为倍数法加权，与本框架的股息贴现不同；日更停在 2026-08-10。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '研究推导：2026—2035 年经营与现金桥接假设', '研究推导', '本研究', '2026-10-22', NULL, '研究推导', '待核验', '2026-10-22', '新签合同额、收入转化率、核心利润率、减值、折旧、税率与少数股东、营运资本、维持/扩张资本、净借款、派息率路径的推导过程，见判断 J-Q、J-P、J-M、J-IMP、J-WC、J-CAPEX、J-DEBT、J-PAYOUT。', '判断成分高，需逐项核验。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）', '数据库取数', '岗底斯', '2026-10-23', NULL, '三级·第三方数据', '待核验', '2026-10-23', '中国中铁、中国铁建、中国交建、中国电建、中国中冶、上海建工、保利发展 2025 年营收、营业成本、归母净利、少数股东损益与减值（年报利润表）；同业 ROE 与 PB（2026-10-22）；同业对比里的分业务竞争格局（工业厂房、房建、基建、模块化建筑）、同业 2026 年新签、鸿路钢构与万喜等对标。', '利润表科目来自年报；ROE、PB、同业新签与竞争格局描述来自岗底斯 AI 汇总，未逐项与原文核对。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国建筑业协会：2025 年建筑业发展统计分析（2026-02）', '数据库取数', '中国建筑业协会（经岗底斯检索）', '2026-02-06', NULL, '二级·官方统计', '数值已核对', '2026-10-23', '2025 年全国建筑业总产值 303,818 亿元（−5.43%，近十年首次下降）、新签合同额 315,327 亿元（−5.51%，连续三年下降）、房屋施工面积 −15.03%、从业人数 −12.97%；八大建筑央企新签占全国比重 2013 年 24.38% → 2024 年 47.43%（券商月报，2026-01）。', '协会报告经岗底斯检索到公众号转载与宁波建工 2025 年报的引用，数字一致，原文未下载；八大央企占比来自券商统计。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '岗底斯：地产同业销售排名与 2025 年业绩（克而瑞、中指院、公司公告）', '数据库取数', '岗底斯（克而瑞、中指院、公司公告）', '2026-06-02', NULL, '三级·第三方数据', '待核验', '2026-10-23', '2025 年房企权益与全口径销售排名；中国海外发展 2025 年业绩公告（收入、毛利率、股东应占溢利、融资成本、土储、已售未结转）；华润置地、保利发展 2025 年业绩；2026 年 1—5 月重点房企销售。', '销售排名来自第三方机构统计；中国海外发展数字取自业绩公告原文片段，保利发展取自年报利润表，华润置地取自券商点评。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国建筑 2024 年年度报告', '定期报告', '中国建筑', '2025-04-16', NULL, '一级·法定披露', '仅定位入口', '2026-10-23', 'ENR“全球最大 250 家工程承包商”首位；标普、穆迪、惠誉评级 A/A2/A（全球建筑行业最高）；国内绝大多数 300 米以上超高层由中国建筑承建；2022—2024 年分业务成本构成。', '经岗底斯知识库检索取得原文片段（file-id 9105961），全文未下载。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '研究推导：商业模式、产业链与五力、竞争对手、竞争壁垒、论点与辩论、适配度（2026-10-23）', '研究推导', '本研究', '2026-10-23', NULL, '研究推导', '待核验', '2026-10-23', '商业模式画布 9 项、产业链 11 个环节、竞争对手 10 家、候选壁垒 7 项（局部优势 3、待验证 1、伪壁垒 3）、论点 8 条（7 条做过正反辩论）、适配度 15/40 的推导过程。岗底斯观点 PK 调用超时，辩论按正反证据组织，裁决是判断。', '判断，不是事实。');
INSERT INTO vi_fact_base (company_id, title, category, statement, period, as_of, verify_status, source_id) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '总股本 413.20 亿股', '治理', '2025 年末与 2026 年中均为 41,320,390,444 股（2024 年回购注销限制性股票后）。每股价值的分母用 413.2039 亿股。', '2026', '2026-06-30', '已核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '中国建筑 2026 年半年度报告' LIMIT 1)),
