UPDATE vi_metric_base SET notes = '跟踪用途：T3：施工毛利率在升、地产在降，综合约 10%。J-M 的核心利润率以此为基础；T3 的自动检查是年度毛利率连续两年低于 9%；验证论点：T3、T9' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '毛利率' AND unit IS NOT DISTINCT FROM '%' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：看同比；T8：减值 2026 年见顶。管理层说全年不超过 2025 年（258.7 亿元）；J-IMP 按 2026 年约 235 亿元（同比约 −9%）；验证论点：T8' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '资产及信用减值损失' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：T1 的核心证据：寒冬里集中度提升。2024 年约 12.2%、2025 年约 13.2%；份额每年提高约 1 个百分点，才能抵消行业每年约 5% 的下滑（T2）；验证论点：T1、T2、T9', source_name = '公司年报建筑业务新签 ÷ 中国建筑业协会《建筑业发展统计分析》全国建筑业企业新签合同额（每年 2—3 月）' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '建筑新签占全国比重' AND unit IS NOT DISTINCT FROM '%' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：看同比；T2 的直接验证。J-P 假设 2026 年收入 −9.7%（上半年 −12%、下半年约 −8%），2027 年再降约 2% 后见底；验证论点：T2', source_name = '财务数据（季报利润表）→ tools/track_fetch.py' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '营业收入' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：T3 的红线：地产收入约占 15%、利润约占三分之一；毛利率跌到 12% 以下，综合毛利率约降 0.3pt，减值压力也会上升（T8）；验证论点：T3、T8', source_name = '半年报、年报“主营业务分行业”房地产开发与投资毛利率' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '地产业务毛利率' AND unit IS NOT DISTINCT FROM '%' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：T6：每股股息不降、派息率逐年提高；J-PAYOUT 假设 2026 年度每股股息持平（0.2718 元）；验证论点：T6', source_name = '年报利润分配预案（每年 3—4 月）' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '每股现金分红' AND unit IS NOT DISTINCT FROM '元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：看同比；订单是收入的源头。J-Q 假设 2026—2028 年新签与 2025 年持平（同比 0）；份额提升（T1）应让公司新签好于全国；验证论点：T1、T2', source_name = '公司每月中下旬发布的《经营情况简报》（上交所公告），取“新签合同总额”累计同比', frequency = '月' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '新签合同总额' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：看同比；收入的领先指标：新开工领先收入 1—2 年。2026 年 1—9 月 −18.1%，降幅不收窄则 2027 年收入见底的假设偏乐观；验证论点：T2', source_name = '《经营情况简报》（季度月份附房建新开工、竣工、施工面积）', frequency = '季' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '房屋建筑新开工面积' AND unit IS NOT DISTINCT FROM '万㎡' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：看同比；T4、T8：份额是不是用垫资换来的。两年增长 70%，而收入在降；增速高于 15% 说明营运资本占用还在扩大；验证论点：T1、T4、T8' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '应收账款＋合同资产' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：化债是 T4 的主要正方证据：2025 年政府债权回收超 1,500 亿元，2026 年上半年清收逾期超 800 亿元；管理层说力度较去年减弱；验证论点：T4', source_name = '半年报、年报经营情况讨论与业绩说明会（上半年录上半年，下半年录全年减上半年）' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '清收政府逾期债权' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：看同比；地产结转的源头；销售面积已 −30%，2028 年后结转规模会下降（T3 反方）；验证论点：T3、T8', source_name = '《经营情况简报》“地产业务合约销售额”累计同比', frequency = '月' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '地产合约销售额' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '股价只进入对比层，不进入经营假设。2026-07-16 除息 0.2718 元，不复权序列在这一天有一个跳空。
跟踪用途：估值只用一个逻辑：按市价买入的隐含年化回报 vs 门槛 6%。基准情景下 7.16 元对应隐含回报 6%（门槛），3.96 元对应 10%（姜诚要求的两位数）。模型更新后重算这两条线' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '中国建筑收盘价' AND unit IS NOT DISTINCT FROM '元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：T4：利润正在变成现金。2025 年 205 亿元；管理层说 2026 年在上年基础上增长；J-WC 假设营运资本占用逐年下降；验证论点：T4' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '经营活动现金流量净额' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：看同比；风险 R5：存量 PPP 约 4,900 亿元，接近归母净资产；2023 年 11 月后不再新增，应该只减不增；验证论点：T4、T8' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = 'PPP 相关长期资产（其他非流动资产＋长期应收款）' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

UPDATE vi_metric_base SET notes = '跟踪用途：T5：负债可控。2025 年末 9,405 亿元；J-DEBT 假设 2026 年净借款约 200 亿元；验证论点：T5' WHERE id = (SELECT id FROM vi_metric_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND name = '带息负债' AND unit IS NOT DISTINCT FROM '亿元' ORDER BY id LIMIT 1);

